/**
 * config/multer.js
 * ---------------------------------------------------------------------------
 * All Multer (file upload) configuration for the ISMS project.
 *
 * Upload rules (see README "Security" notes):
 *   - CV           : PDF, DOC, DOCX  -> uploads/cv
 *   - Documents    : PDF, JPG, PNG    -> uploads/documents
 *   - Company logo : PDF, JPG, PNG    -> uploads/logos
 *   - Size limit   : 5 MB per file (configurable through .env)
 *
 * Every stored filename is generated by us (timestamp + random token +
 * sanitised original name) so that user supplied names can never break out
 * of the uploads folder or overwrite an existing file.
 *
 * IMPORTANT: the uploads folder is *never* mounted as a static folder. Files
 * are only reachable through the authenticated download routes in
 * routes/files.js so that CVs stay private.
 */
'use strict';

const path = require('path');
const fs = require('fs');
const crypto = require('crypto');
const multerPkg = require('multer');

// multer 2.x exports the factory directly, 1.x exposes it as `.multer`
const multer = multerPkg.multer || multerPkg;

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------
const MAX_FILE_SIZE_MB = parseInt(process.env.MAX_FILE_SIZE_MB || '5', 10) || 5;
const MAX_FILE_SIZE = MAX_FILE_SIZE_MB * 1024 * 1024; // bytes
const MAX_FILES = parseInt(process.env.MAX_FILES_PER_UPLOAD || '5', 10) || 5;

const UPLOAD_ROOT = path.join(__dirname, '..', 'uploads');
const DIRS = {
  cv: path.join(UPLOAD_ROOT, 'cv'),
  documents: path.join(UPLOAD_ROOT, 'documents'),
  logos: path.join(UPLOAD_ROOT, 'logos')
};

// Allowed mime types per upload kind (Multer also checks `fileFilter`).
const MIME_TYPES = {
  cv: ['application/pdf', 'application/msword', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'],
  documents: ['application/pdf', 'image/jpeg', 'image/png'],
  logos: ['application/pdf', 'image/jpeg', 'image/png']
};

const EXTENSIONS = {
  cv: ['.pdf', '.doc', '.docx'],
  documents: ['.pdf', '.jpg', '.jpeg', '.png'],
  logos: ['.pdf', '.jpg', '.jpeg', '.png']
};

// Human readable labels used in error messages.
const LABELS = { cv: 'CV', documents: 'document', logos: 'logo' };

// ---------------------------------------------------------------------------
// Make sure the upload directories exist before the first request.
// ---------------------------------------------------------------------------
Object.values(DIRS).forEach((dir) => fs.mkdirSync(dir, { recursive: true }));

/**
 * Turn an arbitrary user supplied filename into a safe, unique filename.
 * @param {string} originalname
 * @returns {string} e.g. 1712345678901-a1b2c3d4-resume.pdf
 */
function safeFilename(originalname) {
  const ext = path.extname(String(originalname || '')).toLowerCase().replace(/[^.a-z0-9]/g, '');
  const base = path
    .basename(String(originalname || 'file'), ext)
    .replace(/[^a-zA-Z0-9._-]/g, '_')
    .replace(/_+/g, '_')
    .slice(0, 60) || 'file';
  return `${Date.now()}-${crypto.randomBytes(4).toString('hex')}-${base}${ext}`;
}

/**
 * Build a disk-storage engine that writes into `uploads/<kind>`.
 * @param {'cv'|'documents'|'logos'} kind
 */
function storageFor(kind) {
  return multer.diskStorage({
    destination(req, file, cb) {
      fs.mkdirSync(DIRS[kind], { recursive: true });
      cb(null, DIRS[kind]);
    },
    filename(req, file, cb) {
      cb(null, safeFilename(file.originalname));
    }
  });
}

/**
 * Build a fileFilter that rejects anything outside the allow-list.
 * @param {'cv'|'documents'|'logos'} kind
 */
function filterFor(kind) {
  return function fileFilter(req, file, cb) {
    const ext = path.extname(file.originalname || '').toLowerCase();
    const okMime = MIME_TYPES[kind].includes(file.mimetype);
    const okExt = EXTENSIONS[kind].includes(ext);

    if (okMime && okExt) return cb(null, true);

    const err = new Error(
      `Invalid ${LABELS[kind]} file "${file.originalname}". Allowed types: ${EXTENSIONS[kind].join(', ')} (max ${MAX_FILE_SIZE_MB} MB).`
    );
    err.code = 'INVALID_FILE_TYPE';
    err.status = 400;
    return cb(err);
  };
}

/** Options object with a friendly error message when the size limit is hit. */
function limitsFor(count) {
  return {
    fileSize: MAX_FILE_SIZE,
    files: count
  };
}

/**
 * Create an upload middleware.
 * @param {'cv'|'documents'|'logos'} kind
 * @param {{field:string, count?:number}} opts
 */
function makeUploader(kind, { field, count = 1 }) {
  return multer({ storage: storageFor(kind), fileFilter: filterFor(kind), limits: limitsFor(count) });
}

// ---------------------------------------------------------------------------
// Public uploaders used by the routers
// ---------------------------------------------------------------------------
/** CV upload (single file) - middleware name: uploadCv */
const uploadCv = makeUploader('cv', { field: 'cv', count: 1 });

/** CV upload OR reuse of the CV already stored on the profile. */
const uploadCvSingle = multer({ storage: storageFor('cv'), fileFilter: filterFor('cv'), limits: limitsFor(1) }).single('cv');

/** Additional documents (multi file, up to MAX_FILES). */
const uploadDocs = multer({ storage: storageFor('documents'), fileFilter: filterFor('documents'), limits: limitsFor(MAX_FILES) }).array('documents', MAX_FILES);

/** Company logo (single file). */
const uploadLogo = makeUploader('logos', { field: 'logo', count: 1 }).single('logo');

/**
 * The application form sends two different things in one request:
 *   - `cv`         : an optional freshly uploaded CV (1 file)
 *   - `documents`  : optional supporting documents (up to MAX_FILES)
 * Both are validated with their own type allow-list, which is why we use
 * `.fields()` with two differently configured disk storages.
 */
const uploadApplication = multer({
  storage: multer.diskStorage({
    destination(req, file, cb) {
      const kind = file.fieldname === 'cv' ? 'cv' : 'documents';
      fs.mkdirSync(DIRS[kind], { recursive: true });
      cb(null, DIRS[kind]);
    },
    filename(req, file, cb) {
      cb(null, safeFilename(file.originalname));
    }
  }),
  fileFilter(req, file, cb) {
    const kind = file.fieldname === 'cv' ? 'cv' : 'documents';
    return filterFor(kind)(req, file, cb);
  },
  limits: { fileSize: MAX_FILE_SIZE, files: 1 + MAX_FILES }
}).fields([{ name: 'cv', maxCount: 1 }, { name: 'documents', maxCount: MAX_FILES }]);

/**
 * Store an already-generated buffer (used by the seed script to create
 * placeholder CV files).
 * @param {Buffer} buffer
 * @param {string} originalName
 * @param {'cv'|'documents'|'logos'} kind
 * @returns {string} the generated filename
 */
function storeBuffer(buffer, originalName, kind) {
  fs.mkdirSync(DIRS[kind], { recursive: true });
  const name = safeFilename(originalName);
  fs.writeFileSync(path.join(DIRS[kind], name), buffer);
  return name;
}

/** Human readable byte size, used when rendering file lists. */
function humanSize(bytes) {
  if (!bytes && bytes !== 0) return '-';
  const units = ['B', 'KB', 'MB', 'GB'];
  let i = 0;
  let n = bytes;
  while (n >= 1024 && i < units.length - 1) {
    n /= 1024;
    i += 1;
  }
  return `${n.toFixed(n < 10 && i > 0 ? 1 : 0)} ${units[i]}`;
}

module.exports = {
  uploadCv,
  uploadCvSingle,
  uploadDocs,
  uploadLogo,
  uploadApplication,
  safeFilename,
  storeBuffer,
  humanSize,
  DIRS,
  UPLOAD_ROOT,
  EXTENSIONS,
  MIME_TYPES,
  MAX_FILE_SIZE,
  MAX_FILE_SIZE_MB,
  MAX_FILES
};